import { parseRequest, problemResponse, redirect } from "./http.mjs";
import { authorize } from "./auth.mjs";
import { assertId, isReserved, isValidSpaceId } from "./ids.mjs";
import { spaceUrl, collectionUrl } from "./meta.mjs";
import { methodNotAllowed, notFound } from "./problems.mjs";

// The wrapper every endpoint function is built from:
//
//   export const lambdaHandler = handler(operation, { scope, ... })
//
// It parses the event, resolves the ids the route addresses, applies the
// authorization decision, runs the operation, and turns a thrown problem
// into its problem+json response. The function's own file is then the
// operation and nothing else.
//
// `scope` names what the route addresses:
//   "space"       /space/{s}/{c} with an empty collection_id: the Space
//                 container (a non-empty id is the bare Collection URL,
//                 answered with a 308; a reserved id is 405)
//   "collection"  /space/{s}/{c}/{r} with an empty resource_id: the
//                 Collection container (a non-empty id is a Resource, which
//                 the GET and DELETE functions also serve)
//   "space-meta", "space-policy", "collection-meta", "collection-policy",
//   "resource", "resource-meta", "resource-policy"
//
// Options: `listing` (unauthorized answers empty, never 404), `rootOnly`
// (the container rule), `readable` (false for policies, which are never
// public).

export function handler(operation, { scope, listing = false, rootOnly = false, readable = true } = {}) {
  // An option may depend on the resolved route (the GET and DELETE on the
  // collection container route serve a Resource when the id is non-empty).
  const resolve = (option, route) => (typeof option === "function" ? option(route) : option);
  return async (event) => {
    const req = parseRequest(event);
    try {
      const route = resolveRoute(req, scope);
      if (route.redirect) {
        return redirect(req, route.redirect);
      }
      await authorize(req, route, {
        listing: resolve(listing, route),
        rootOnly: resolve(rootOnly, route),
        readable,
      });
      return await operation(req, route);
    } catch (err) {
      return problemResponse(req, err);
    }
  };
}

// The wrapper for endpoints outside a Space (the service description, the
// Spaces Repository): parsing and problem handling only; the operation
// makes its own authorization decision from the request context.
export function plainHandler(operation) {
  return async (event) => {
    const req = parseRequest(event);
    try {
      return await operation(req);
    } catch (err) {
      return problemResponse(req, err);
    }
  };
}

// For the two container scopes, whether the delivered path is the container
// itself (empty final segment), the bare form of a sub-container (308), a
// reserved segment (405), or -- on the "collection" scope -- a Resource.
function resolveRoute(req, scope) {
  const { space_id: spaceId, collection_id: collectionId, resource_id: resourceId } = req.pathParameters;
  if (!isValidSpaceId(spaceId)) {
    throw notFound();
  }
  const route = { spaceId, registryUrl: `${req.base}/space/${spaceId}` };

  if (scope === "space") {
    if (!collectionId) {
      return route;
    }
    if (isReserved("collection", collectionId)) {
      throw methodNotAllowed();
    }
    assertId("collection", collectionId);
    return { ...route, redirect: collectionUrl(req, spaceId, collectionId) };
  }

  if (scope === "space-meta" || scope === "space-policy") {
    return route;
  }

  assertId("collection", collectionId);
  route.collectionId = collectionId;

  if (scope === "collection") {
    if (!resourceId) {
      return route;
    }
    if (isReserved("resource", resourceId)) {
      throw methodNotAllowed();
    }
    assertId("resource", resourceId);
    return { ...route, resourceId };
  }

  if (scope === "collection-meta" || scope === "collection-policy") {
    return route;
  }

  // The Resource scopes: PUT on the Collection container is not an operation.
  if (!resourceId) {
    throw methodNotAllowed();
  }
  assertId("resource", resourceId);
  return { ...route, resourceId };
}

export { spaceUrl, collectionUrl };
